import{_ as d,h as n,i as a,c as r,v as o,p as s,x as c,m as i,e as l,S as m}from"./chunks/framework.Dvtg8yj2.js";const f=JSON.parse('{"title":"JSON / 结构化输出","description":"","frontmatter":{"title":"JSON / 结构化输出","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/json-schema-decode.md","filePath":"llm/json-schema-decode.md","lastUpdated":1788454257000}'),h={name:"llm/json-schema-decode.md"};function p(u,e,E,S,A,O){const t=n("Mermaid");return a(),r("div",null,[e[1]||(e[1]=o('<h1 id="json-结构化输出" tabindex="-1">JSON / 结构化输出 <a class="header-anchor" href="#json-结构化输出" aria-label="Permalink to &quot;JSON / 结构化输出&quot;">​</a></h1><div class="epigraph"><p>产品要的是能通过 schema 校验的对象，不是「看起来像 JSON」的散文；把 schema 编译进逐步掩码，合法集合在解码时就是闭的。</p><footer>—— 对照 JSON Schema 规范与 OpenAI Structured Outputs；解码引擎见 Willard 与 Louf 的引导生成及后续 CFG 实现</footer></div><p>接口下游是解析器、数据库写入或另一个智能体。它们接受的是类型闭合的对象：缺字段、多余逗号、字符串里未转义的换行，都会在 <code>json.loads</code> 或校验器上炸掉。提示「请只输出 JSON」能把一部分概率质量推到花括号附近，却不能在逐步词表上禁止非法 token。JSON / 结构化输出把 <strong>JSON Schema</strong>（或等价类型定义）当成生成契约：要么事后校验再重试，要么在采样时把非法续写掩掉。后者的自动机与词表索引写在 <a href="/llm/constrained-decoding">约束解码</a>；本篇写 schema 作为产品合同、JSON mode 与严格 schema 的档次差、以及它和 <a href="/llm/function-calling">function calling</a> 参数块的分工。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自然语言里的「结构化」是软的。模型可以输出 Markdown 代码围栏、前后解释、单引号、尾逗号、<code>True</code> 而不是 <code>true</code>。Schema 越深——嵌套对象、数组、枚举、<code>oneOf</code>——自由采样越容易在某一层出轨。重试有延迟与费用，且重试提示本身会污染上下文。需要在「完全自由」和「写死模板只填几个槽」之间，有一层按类型收缩支撑集的方法。</p><p>JSON Schema 本身比「是一个 object」苛刻得多：必填键、额外键是否允许、数字区间、字符串 pattern、依赖字段。产品真正要的常常是这张表，而不只是括号匹配。若解码器只保证 RFC 8259 意义上的合法 JSON，仍可能缺 <code>order_id</code>、把枚举写成近义词。问题因此分成两档：语法合法，与 schema 合法。混为一谈会在联调时互相指责。</p><h3 id="json-mode-与-schema-约束不是同一档" tabindex="-1">JSON mode 与 Schema 约束不是同一档 <a class="header-anchor" href="#json-mode-与-schema-约束不是同一档" aria-label="Permalink to &quot;JSON mode 与 Schema 约束不是同一档&quot;">​</a></h3><p>JSON mode 通常只约束「输出是一个 JSON 值」：对象或数组能闭合，字符串转义合法。它不规定键名集合。严格 schema 模式把 <code>properties</code>、<code>required</code>、<code>enum</code> 编进文法，键顺序有时还被固定以缩小语言。OpenAI 的 Structured Outputs、各引擎的 <code>guided_json</code> / grammar，都属于后一档的产品名；实现仍是逐步掩码或外部校验循环。选档时看下游：只做日志展示，mode 够用；要写入强类型 API，必须 schema。</p><p><span class="marginnote">Schema 合法仍可能语义荒谬：<code>&quot;age&quot;: -3</code> 若类型是 integer 且未写 minimum，校验会放行。类型层与业务层要分开。把所有业务规则塞进 JSON Schema 的 pattern，会得到巨大、易炸的自动机，编译期先失败。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先写一份与代码生成器同源的 schema，不要在提示里手抄一份、在校验器里再写一份。对象的 <code>additionalProperties</code> 默认是否允许，决定模型能不能发明键；生产入库应关掉。枚举用 schema 的 <code>enum</code> 而不是在 description 里列同义词。可选字段不要和「空字符串表示缺失」混用，否则解码器允许 <code>&quot;&quot;</code>，下游又当缺失，行为分叉。</p><p>解码路径有三条。第一条：自由生成，事后用校验器，失败则把错误信息拼回对话再生成——实现简单，尾延迟差，且模型可能在解释错误时再次跑偏。第二条：JSON mode，语法闭合后再校验 schema，失败重试。第三条：把 schema 编译成 FSM / CFG，逐步只允许合法 token，一次通过的概率最高，编译与状态内存是代价。嵌套很深、pattern 很狂时，第三条会在编译期爆炸，应简化 schema 或改走校验循环。工具参数是第三条的典型客户：字段少、类型硬、失败代价高。</p>',12)),(a(),s(m,null,{default:c(()=>[l(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22JSON%20Schema%22%5D%20--%3E%20C%7B%22%E7%BA%A6%E6%9D%9F%E5%BC%BA%E5%BA%A6%22%7D%0A%20%20C%20--%3E%7C%E4%BB%85%E8%AF%AD%E6%B3%95%7C%20JM%5B%22JSON%20mode%20%2F%20%E6%8B%AC%E5%8F%B7%E6%96%87%E6%B3%95%22%5D%0A%20%20C%20--%3E%7C%E9%94%AE%E4%B8%8E%E7%B1%BB%E5%9E%8B%7C%20G%5B%22%E7%BC%96%E8%AF%91%20FSM%20%E6%88%96%20PDA%22%5D%0A%20%20JM%20--%3E%20V%5B%22%E4%BA%8B%E5%90%8E%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20G%20--%3E%20D%5B%22%E9%80%90%E6%AD%A5%E6%8E%A9%E7%A0%81%E9%87%87%E6%A0%B7%22%5D%0A%20%20V%20--%3E%7C%E5%A4%B1%E8%B4%A5%7C%20R%5B%22%E5%9B%9E%E5%A1%AB%E9%94%99%E8%AF%AF%E5%86%8D%E7%94%9F%E6%88%90%22%5D%0A%20%20D%20--%3E%20OBJ%5B%22%E7%B1%BB%E5%9E%8B%E9%97%AD%E5%90%88%E7%9A%84%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20V%20--%3E%7C%E9%80%9A%E8%BF%87%7C%20OBJ%0A"})]),fallback:c(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h3 id="schema-编译进解码器" tabindex="-1">Schema 编译进解码器 <a class="header-anchor" href="#schema-编译进解码器" aria-label="Permalink to &quot;Schema 编译进解码器&quot;">​</a></h3><p>编译器面对的不是字符文法，而是 BPE / 词表。数字 <code>123</code> 可能是一个 token 或三个；<code>&quot;: &quot;</code> 可能粘在键名后。约束引擎必须在 token 字母表上定义合法前缀，细节见 <a href="/llm/constrained-decoding">约束解码</a> 里的可表示性空洞。工程上应固定分词器再编译文法，换模型等于重编译。键顺序若强制字典序或 schema 声明序，掩码更紧、更快，但与「JSON 对象无序」的直觉冲突——文档里要写死，客户端反序列化本来也不依赖序。</p><p>流式输出时，未闭合的对象对 <code>json.loads</code> 非法。要么等结束再解析，要么用支持增量的解析器按自动机状态展示草稿。不要把半截流式 JSON 直接写入数据库。<code>null</code>、空数组、缺键是三种不同的业务含义，schema 里应显式取舍，而不是指望模型「看着办」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>掩码把每一步的分布改成条件于「当前前缀已是某合法 schema 前缀」。模型仍按 \\(p_\\theta\\) 在合法集合上打分；集合很小且模型很差时，会出现重复标点或极慢的挤牙膏——那是截断分布质量差，不是校验器坏了。固定键序相当于把对象语言变成近似的正则或浅 CFG，状态数下降。<code>oneOf</code> 与递归 <code>$ref</code> 把语言推向 CFG，需要下推自动机，缓存未命中时逐步开销上升。</p><p>与 function calling 的分工是：工具循环关心 <em>何时调用、调用谁</em>；结构化输出关心 <em>这一段 token 能否成为指定类型的值</em>。工具的 <code>arguments</code> 往往就是一份小 schema。完整助手答复也可以是一个 JSON 对象（例如只返回 <code>answer</code> 与 <code>citations</code>），这时没有工具角色，但仍走同一套解码。不要把「返回 JSON」实现成再包一层假工具，那会污染消息角色、让模板更脆。</p><p><span class="marginnote">温度与 schema 一起作用。高温会在合法键之间乱跳，但仍被掩码挡在类型外；低温加过紧 schema 可能总走同一骨架。评测结构化任务时，采样参数属于实验条件，见 <a href="/llm/sampling-temperature-topp">Temperature / Top-k / Top-p</a>。</span></p><h3 id="与-function-calling-的分工" tabindex="-1">与 function calling 的分工 <a class="header-anchor" href="#与-function-calling-的分工" aria-label="Permalink to &quot;与 function calling 的分工&quot;">​</a></h3><p>若产品只要一个对象、没有副作用，用结构化输出即可，不必走工具协议。若对象来自外部系统，应调用工具，观察可以是 JSON，最终用户可见答复可以是自然语言或另一份 schema。两套 schema 不要同名不同义。并行工具调用时，每个 <code>arguments</code> 独立约束；不要用一个巨大 JSON 把多次调用捏在一起，那会让部分失败无法按 id 回填。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>结构化输出不提高事实准确率。合法的 <code>&quot;capital&quot;: &quot;悉尼&quot;</code> 仍然是错的。要把事实钉住，用检索或工具，见 <a href="/llm/rag-chunking">向量检索与切分</a>。它也不替代鉴权：生成符合 schema 的删除指令，执行权仍在宿主。超大 schema（整份 OpenAPI）不适合一次性编进逐步掩码，应拆成小对象或只约束顶层信封。</p><p>各引擎的 JSON 实现覆盖面不同：unicode 转义、数字的科学计数法、对 <code>format: date-time</code> 是文法还是事后正则，都要实测。不要假设云厂商的 Structured Outputs 与开源 <code>guided_json</code> 在失败时行为一致——有的抛错，有的回退自由生成。回退最危险：表面上「总有输出」，类型契约已经破了。客户端应校验，不要只信响应头里的 <code>json_object</code> 标记。</p><p><span class="marginnote">引用 JSON Schema 规范、OpenAI Structured Outputs 说明、以及 <a href="/llm/constrained-decoding">约束解码</a> 所列的 Outlines / XGrammar 论文。不要把某一版云 API 的字段名写成 IETF 标准。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>JSON mode 保证语法闭合；严格 schema 才保证键、类型与枚举。</li><li>产品契约应与代码同源；<code>additionalProperties</code>、缺键与空字符串要显式定义。</li><li>逐步掩码一次通过最好，复杂 pattern 可能迫使改回校验—重试。</li><li>Token 化与 schema 字母表不对齐会造成空洞，须锁定分词器再编译。</li><li>结构合法不等于事实正确，也不等于已授权执行。</li><li>工具参数与助手侧 JSON 答复共用同一套类型思想，但角色不同，不要用假工具硬套。</li><li>出处：JSON Schema；OpenAI Structured Outputs；Willard &amp; Louf, arXiv:2307.09702；Dong et al., XGrammar, arXiv:2411.15100。</li></ul>',15))])}const N=d(h,[["render",p]]);export{f as __pageData,N as default};
